/**
 * Unit tests for TreeTraversingParser.getIntValue().
 */
public class TreeTraversingParser_getIntValue_TriageGen0Test {

    private ObjectMapper mapper;

    @Before
    public void setUp() {
        mapper = new ObjectMapper();
    }





    /**
     * Tests getIntValue when the current node is a Decimal/Double node.
     */
    @Test
    public void testGetIntValue_SuccessWithDecimalNode() throws IOException {
        JsonNode decimalNode = mapper.getNodeFactory().numberNode(123.45);
        TreeTraversingParser parser = new TreeTraversingParser(decimalNode);

        // Jackson's NumericNode.intValue() typically truncates
        int result = parser.getIntValue();

        Assert.assertEquals(123, result);
    }




}

